package android.preference;public class ListPreference extends Preference{public CharSequence[] labels,values;String value;public ListPreference(android.content.Context c){super(c);}public void setDefaultValue(Object v){}public void setEntries(CharSequence[] e){labels=e;}public void setEntryValues(CharSequence[] e){values=e;}public void setValue(String v){value=v;}public String getValue(){return value;}}
